<?php

declare(strict_types=1);

namespace App\Services\Audits\Rules;

final class RuleCatalog
{
    /**
     * @return list<RuleDefinition>
     */
    public function all(): array
    {
        $t = 'technical_seo';
        $p = 'performance';
        $o = 'on_page_seo';
        $m = 'mobile_ux';
        $s = 'security';
        $c = 'conversion';
        $v = 'search_visibility';

        return [
            $this->rule($t, 'https_enabled', 'critical', 'سایت از HTTPS استفاده نمی‌کند.', 'ارتباط کاربران با سایت ممکن است ناامن دیده شود و این موضوع می‌تواند روی اعتماد اثر بگذارد.', 'گواهی معتبر نصب کنید و همه نشانی‌ها را به HTTPS منتقل کنید.'),
            $this->rule($t, 'http_status', 'critical', 'صفحه اصلی پاسخ موفق برنمی‌گرداند.', 'اگر صفحه اصلی در دسترس نباشد، کاربر و موتور جستجو ممکن است به سایت نرسند.', 'وضعیت HTTP صفحه اصلی را بررسی کنید و آن را به پاسخ ۲۰۰ برسانید.'),
            $this->rule($t, 'redirect_chain', 'high', 'زنجیره ریدایرکت طولانی است.', 'ریدایرکت‌های پشت‌سرهم می‌توانند دسترسی کاربر را کندتر کنند.', 'مقصد نهایی را مستقیم کنید تا بیش از یک ریدایرکت لازم نباشد.'),
            $this->rule($t, 'canonical_present', 'medium', 'نشانی کنونیکال برای این صفحه مشخص نشده است.', 'بدون کنونیکال، نسخه ترجیحی صفحه ممکن است برای موتور جستجو مبهم بماند.', 'برای هر صفحه مهم یک نشانی کنونیکال مشخص کنید.'),
            $this->rule($t, 'robots_txt', 'low', 'فایل robots.txt پیدا نشد.', 'نبود این فایل الزاماً مانع ایندکس نیست، اما کنترل خزش را سخت‌تر می‌کند.', 'یک robots.txt معتبر در ریشه سایت قرار دهید.'),
            $this->rule($t, 'sitemap_xml', 'medium', 'نقشه سایت در دسترس نیست.', 'نبود نقشه سایت می‌تواند کشف صفحات را برای موتور جستجو کندتر کند.', 'نقشه XML بسازید و آن را در robots.txt معرفی کنید.'),
            $this->rule($t, 'noindex_directive', 'high', 'این صفحه با دستور noindex از ایندکس شدن منع شده است.', 'صفحه‌ای که noindex دارد ممکن است در نتایج جستجو نمایش داده نشود.', 'اگر این صفحه باید دیده شود، دستور noindex را بردارید.'),
            $this->rule($t, 'meta_robots', 'low', 'دستور nofollow روی این صفحه دیده شد.', 'nofollow می‌تواند دنبال‌کردن لینک‌های صفحه را محدود کند.', 'فقط در صفحاتی که عمدی است از nofollow استفاده کنید.'),
            $this->rule($t, 'hreflang', 'info', 'برچسب hreflang دیده نشد.', 'اگر سایت چندزبانه باشد، نبود hreflang می‌تواند نسخه درست را مبهم کند.', 'اگر سایت چندزبانه است hreflang را اضافه کنید؛ در غیر این صورت این مورد نیاز به بررسی انسانی دارد.'),
            $this->rule($t, 'url_structure', 'low', 'ساختار برخی نشانی‌ها می‌تواند ساده‌تر شود.', 'نشانی‌های طولانی یا پر از پارامتر ممکن است برای کاربر و جستجو خواناتر نباشند.', 'نشانی‌های کوتاه، خوانا و پایدار بسازید.'),
            $this->rule($t, 'broken_internal_links', 'high', 'لینک داخلی خراب پیدا شد.', 'لینک خراب می‌تواند کاربر را به بن‌بست برساند و کشف صفحات را مختل کند.', 'مقصد لینک‌های داخلی را اصلاح کنید یا لینک را حذف کنید.'),
            $this->rule($t, 'structured_data', 'low', 'داده ساختاریافته در صفحات بررسی‌شده دیده نشد.', 'داده ساختاریافته می‌تواند نمایش نتیجه را غنی‌تر کند، اما نبود آن به معنی حذف از جستجو نیست.', 'در صورت تناسب، نوع مناسب Schema.org را به صفحه اضافه کنید.'),

            $this->rule($o, 'missing_title', 'high', 'عنوان صفحه وجود ندارد.', 'نبود عنوان می‌تواند روی تشخیص موضوع صفحه در نتایج جستجو اثر بگذارد.', 'برای صفحه یک عنوان روشن و یکتا بنویسید.'),
            $this->rule($o, 'title_length', 'low', 'طول عنوان صفحه خارج از بازه پیشنهادی است.', 'عنوان خیلی کوتاه یا خیلی بلند ممکن است در نتایج ناقص دیده شود.', 'عنوان را حدود ۳۰ تا ۶۰ نویسه و مرتبط با محتوای صفحه بنویسید.'),
            $this->rule($o, 'duplicate_titles', 'medium', 'چند صفحه عنوان یکسان دارند.', 'عنوان تکراری می‌تواند تشخیص تفاوت صفحات را سخت‌تر کند.', 'برای هر صفحه عنوان یکتا بنویسید.'),
            $this->rule(
                $o,
                'missing_meta_description',
                'medium',
                'توضیحات متا برای این صفحه وجود ندارد.',
                'این موضوع می‌تواند روی نحوه نمایش صفحه در نتایج جستجو تأثیر بگذارد.',
                'برای این صفحه یک توضیحات متای مرتبط و جذاب بنویسید.',
            ),
            $this->rule($o, 'meta_description_length', 'low', 'طول توضیحات متا خارج از بازه پیشنهادی است.', 'توضیحات خیلی کوتاه یا بلند ممکن است در نتیجه جستجو کامل دیده نشود.', 'توضیحات را حدود ۷۰ تا ۱۶۰ نویسه و مرتبط با صفحه بنویسید.'),
            $this->rule($o, 'missing_h1', 'high', 'صفحه عنوان اصلی H1 ندارد.', 'نبود H1 می‌تواند موضوع اصلی صفحه را برای کاربر و موتور جستجو کم‌رنگ کند.', 'یک H1 روشن در بالای محتوای اصلی قرار دهید.'),
            $this->rule($o, 'multiple_h1', 'medium', 'صفحه بیش از یک H1 دارد.', 'چند H1 می‌تواند موضوع اصلی صفحه را مبهم کند.', 'یک H1 اصلی نگه دارید و بقیه را به سطح پایین‌تر ببرید.'),
            $this->rule($o, 'heading_hierarchy', 'medium', 'سلسله‌مراتب تیترها پرش دارد.', 'پرش تیتر می‌تواند خواندن صفحه را برای کاربر و ابزارهای کمکی سخت‌تر کند.', 'تیترها را به ترتیب و بدون پرش سطح بچینید.'),
            $this->rule($o, 'image_alt', 'medium', 'برخی تصویرها متن جایگزین ندارند.', 'نبود متن جایگزین می‌تواند معنا و دسترس‌پذیری تصویر را کم کند.', 'برای تصویرهای محتوایی یک متن جایگزین مرتبط بنویسید.'),
            $this->rule($o, 'content_length', 'medium', 'حجم متن قابل مشاهده این صفحه کم است.', 'متن کم ممکن است پاسخ روشنی به نیاز بازدیدکننده ندهد.', 'محتوای مفید و مرتبط را به اندازه نیاز کاربر کامل کنید.'),
            $this->rule($o, 'open_graph', 'low', 'برچسب‌های Open Graph دیده نشد.', 'بدون این برچسب‌ها، پیش‌نمایش اشتراک‌گذاری ممکن است ناقص باشد.', 'عنوان، توضیح و تصویر Open Graph را اضافه کنید.'),
            $this->rule($o, 'twitter_card', 'low', 'کارت شبکه اجتماعی دیده نشد.', 'نبود کارت می‌تواند پیش‌نمایش اشتراک را ساده‌تر از حد لازم کند.', 'برچسب کارت را برای صفحه‌های مهم اضافه کنید.'),
            $this->rule($o, 'internal_linking', 'low', 'این صفحه لینک داخلی به صفحه دیگری ندارد.', 'لینک داخلی به کاربر کمک می‌کند مسیر بعدی را پیدا کند.', 'از این صفحه به خدمات یا صفحات مرتبط لینک دهید.'),
            $this->rule($o, 'url_readability', 'low', 'خوانایی نشانی این صفحه می‌تواند بهتر شود.', 'نشانی‌های دارای خط زیر یا پسوند فنی برای کاربر کمتر روشن‌اند.', 'نشانی را با واژه‌های خوانا و بدون پسوند غیرضروری بنویسید.'),

            $this->rule($p, 'performance_score', 'high', 'امتیاز سرعت موبایل پایین است.', 'سرعت پایین می‌تواند کاربر را پیش از دیدن پیشنهاد شما از سایت خارج کند.', 'با کاهش حجم صفحه و بهبود پاسخ سرور، امتیاز سرعت موبایل را بالا ببرید.'),
            $this->rule($p, 'lcp', 'high', 'زمان نمایش بزرگ‌ترین بخش صفحه کند است.', 'LCP کند می‌تواند حس کند بودن صفحه را برای بازدیدکننده ایجاد کند.', 'تصویر یا بلوک اصلی بالای صفحه را سبک‌تر و زودتر بارگذاری کنید.'),
            $this->rule($p, 'inp', 'high', 'واکنش صفحه به تعامل کاربر کند است.', 'تأخیر در واکنش می‌تواند تکمیل فرم یا کلیک را سخت‌تر کند.', 'اسکریپت‌های سنگین را کم کنید تا صفحه سریع‌تر به کلیک پاسخ دهد.'),
            $this->rule($p, 'cls', 'high', 'چیدمان صفحه هنگام بارگذاری جابه‌جا می‌شود.', 'جابه‌جایی ناگهانی می‌تواند باعث کلیک اشتباه شود.', 'برای تصویر و تبلیغ فضا رزرو کنید تا صفحه نپرد.'),
            $this->rule($p, 'fcp', 'medium', 'اولین محتوای قابل‌دیدن دیر ظاهر می‌شود.', 'تأخیر در اولین نمایش می‌تواند صفحه را خالی نشان دهد.', 'منابع مسدودکننده رندر را کم کنید.'),
            $this->rule($p, 'ttfb', 'medium', 'پاسخ اولیه سرور کند است.', 'پاسخ دیر سرور می‌تواند کل بارگذاری را عقب بیندازد.', 'زمان پاسخ سرور و کش را بررسی کنید.'),
            $this->rule($p, 'speed_index', 'medium', 'سرعت پر شدن صفحه پایین است.', 'پر شدن کند صفحه می‌تواند انتظار کاربر را طولانی کند.', 'محتوای بالای صفحه را در اولویت بارگذاری قرار دهید.'),
            $this->rule($p, 'total_blocking_time', 'medium', 'زمان مسدود بودن صفحه زیاد است.', 'انسداد طولانی می‌تواند تعامل را به تأخیر بیندازد.', 'کار جاوااسکریپت را در بارگذاری اولیه کم کنید.'),
            $this->rule($p, 'performance_needs_review', 'info', 'داده سرعت آزمایشگاهی در دسترس نیست.', 'بدون این داده، قضاوت درباره سرعت نباید قطعی باشد.', 'کلید PageSpeed را تنظیم کنید یا سرعت را جداگانه بررسی کنید.'),

            $this->rule($m, 'viewport', 'high', 'برچسب viewport موبایل وجود ندارد.', 'بدون viewport، صفحه ممکن است در گوشی درست مقیاس نشود.', 'برچسب viewport را در سرصفحه قرار دهید.'),
            $this->rule($m, 'horizontal_overflow', 'info', 'سرریز افقی نیاز به بررسی انسانی دارد.', 'اسکرول افقی ناخواسته فقط با دیدن صفحه قابل تأیید است.', 'صفحه را در عرض گوشی باز کنید و اسکرول افقی ناخواسته را بررسی کنید.'),
            $this->rule($m, 'text_readability', 'medium', 'اندازه متن در موبایل ممکن است ریز باشد.', 'متن ریز می‌تواند خواندن پیشنهاد را در گوشی سخت کند.', 'اندازه قلم متن اصلی را برای موبایل خوانا کنید.'),
            $this->rule($m, 'tap_targets', 'medium', 'هدف‌های لمسی ممکن است به هم نزدیک باشند.', 'دکمه‌های کوچک یا چسبیده می‌توانند لمس اشتباه ایجاد کنند.', 'فاصله و اندازه دکمه‌ها را برای انگشت کافی کنید.'),
            $this->rule($m, 'mobile_performance', 'high', 'سرعت نسخه موبایل فرصت بهبود دارد.', 'بیشتر بازدیدها ممکن است از گوشی باشد و کندی آنجا اثر بیشتری دارد.', 'نسخه موبایل را با همان اولویت سرعت دسکتاپ بهینه کنید.'),

            $this->rule($s, 'certificate_status', 'critical', 'گواهی HTTPS معتبر به نظر نمی‌رسد.', 'گواهی نامعتبر می‌تواند مرورگر را به هشدار امنیتی وادارد.', 'گواهی را تمدید کنید و زنجیره آن را کامل نصب کنید.'),
            $this->rule($s, 'mixed_content', 'high', 'روی صفحه HTTPS منبع ناامن HTTP دیده شد.', 'محتوای ترکیبی می‌تواند بخشی از صفحه را ناامن نشان دهد.', 'همه تصویرها، اسکریپت‌ها و فایل‌ها را از HTTPS بارگذاری کنید.'),
            $this->rule($s, 'hsts', 'medium', 'سربرگ HSTS تنظیم نشده است.', 'بدون HSTS، مرورگر ممکن است بار اول را هنوز از HTTP آغاز کند.', 'Strict-Transport-Security را روی HTTPS فعال کنید.'),
            $this->rule($s, 'x_content_type_options', 'low', 'سربرگ X-Content-Type-Options دیده نشد.', 'نبود این سربرگ می‌تواند حدس نوع فایل را به مرورگر بسپارد.', 'مقدار nosniff را برای این سربرگ تنظیم کنید.'),
            $this->rule($s, 'content_security_policy', 'low', 'سیاست امنیت محتوا دیده نشد.', 'نبود CSP به معنی نفوذ نیست، اما یک لایه دفاعی کمتر است.', 'یک سیاست محتوا متناسب با منابع واقعی سایت اضافه کنید.'),
            $this->rule($s, 'referrer_policy', 'low', 'سیاست Referrer تنظیم نشده است.', 'بدون این سیاست، نشانی کامل ممکن است به سایت‌های دیگر فرستاده شود.', 'یک Referrer-Policy متناسب، مانند strict-origin-when-cross-origin، تنظیم کنید.'),
            $this->rule($s, 'x_frame_options', 'medium', 'محدودیت نمایش داخل فریم دیده نشد.', 'بدون این محدودیت، صفحه ممکن است داخل سایت دیگری قاب شود.', 'X-Frame-Options یا frame-ancestors را تنظیم کنید.'),

            $this->rule($c, 'phone_number', 'medium', 'شماره تماس قابل‌تشخیص دیده نشد.', 'نبود شماره واضح می‌تواند تماس گرفتن را برای مشتری سخت کند.', 'شماره تماس را به‌صورت متن و لینک tel در صفحه قرار دهید.'),
            $this->rule($c, 'contact_form', 'medium', 'فرم تماس در صفحات بررسی‌شده دیده نشد.', 'نبود فرم می‌تواند یک راه ارتباط را از مشتری بگیرد.', 'یک فرم کوتاه تماس یا درخواست در مسیر اصلی قرار دهید.'),
            $this->rule($c, 'primary_cta', 'medium', 'دعوت به اقدام اصلی دیده نشد.', 'بدون دکمه یا لینک روشن، قدم بعدی مشتری ممکن است نامشخص بماند.', 'یک دعوت مشخص مانند مشاوره یا تماس در صفحه اصلی بگذارید.'),
            $this->rule($c, 'cta_visibility', 'low', 'جایگاه دعوت به اقدام نیاز به بررسی دارد.', 'اگر دعوت پایین صفحه باشد، ممکن است کمتر دیده شود.', 'دعوت اصلی را در بخش بالای صفحه هم نشان دهید.'),
            $this->rule($c, 'whatsapp_or_contact_link', 'low', 'راه سریع پیام‌رسان دیده نشد.', 'برای برخی مشتریان پیام‌رسان مسیر راحت‌تری از فرم است.', 'در صورت تناسب کسب‌وکار، لینک واتساپ یا پیام‌رسان را اضافه کنید.'),
            $this->rule($c, 'service_or_contact_path', 'low', 'مسیر خدمات یا تماس در صفحات خزش‌شده کم‌رنگ است.', 'اگر این مسیرها پیدا نشوند، مشتری ممکن است پیشنهاد را نبیند.', 'صفحه خدمات و تماس را از منو و صفحه اصلی در دسترس بگذارید.'),
            $this->rule($c, 'form_friction', 'medium', 'فرم فیلدهای زیادی دارد.', 'فرم طولانی می‌تواند تکمیل درخواست را کم کند.', 'فرم را به فیلدهای واقعاً لازم محدود کنید.'),

            $this->rule($v, 'indexability', 'critical', 'صفحه اصلی ممکن است قابل ایندکس نباشد.', 'اگر صفحه اصلی noindex یا مسدود باشد، ممکن است در جستجو دیده نشود.', 'دستور noindex و قانون robots صفحه اصلی را فقط اگر عمدی است نگه دارید.'),
            $this->rule($v, 'sitemap_coverage', 'medium', 'بخش کمی از صفحات بررسی‌شده در نقشه سایت هستند.', 'صفحه‌ای که در نقشه نیست ممکن است دیرتر کشف شود.', 'صفحات مهم را به نقشه سایت اضافه کنید.'),
            $this->rule($v, 'canonical_consistency', 'high', 'کنونیکال به میزبان دیگری اشاره می‌کند.', 'کنونیکال خارج از سایت می‌تواند سیگنال صفحه را به جای دیگری ببرد.', 'کنونیکال را به نشانی اصلی همان سایت برگردانید.'),
        ];
    }

    private function rule(
        string $category,
        string $key,
        string $severity,
        string $name,
        string $impact,
        string $recommendation,
    ): RuleDefinition {
        return new RuleDefinition(
            key: $key,
            category: $category,
            name: $name,
            description: $name,
            businessImpact: $impact,
            recommendation: $recommendation,
            severity: $severity,
        );
    }
}
